 "44": {
  "cols": [
   "GDP as a measure of living standards",
   "Why it may not be effective"
  ],
  "left": [
   {
    "title": "What GDP measures",
    "steps": [
     "MeasureWhat it means Real GDPGDP adjusted for inflation, so it measures volume rather than price changes.",
     "Nominal GDPGDP at current prices - rises with inflation even if nothing more is produced.",
     "GDP per capitaReal GDP ÷ population.",
     "Better for living standards, since a country can grow by adding people without anyone being better off.",
     "GNIGross National Income - includes income earned abroad by residents and excludes income earned domestically by foreigners."
    ]
   }
  ],
  "right": [
   {
    "title": "Real GDP does not always mean higher living standards",
    "steps": [
     "No, because the measure and the thing it is standing in for can move apart.",
     "In developing countries a rise in recorded GDP may partly reflect more activity being recorded as farming and trade become formalised, rather than more being produced.",
     "GDP counts the output but not the distribution: average income can rise while most people see no gain.",
     "It ignores non-monetary factors - leisure, health, environmental quality, work-life balance."
    ]
   },
   {
    "title": "The Easterlin paradox: more income, not more happiness",
    "steps": [
     "Happiness does not necessarily rise in line with economic growth.",
     "If everyone in a country gets richer, average happiness stays roughly the same over time.",
     "The explanation is that people care most about RELATIVE income: being richer than the people around you makes you happier.",
     "So being poor in a rich country can leave you less happy than being rich in a poor country, even if the first person has the higher absolute income and material standard of living."
    ]
   },
   {
    "title": "Unrecorded output",
    "steps": [
     "In developing countries a rise in recorded GDP may partly reflect more activity being recorded as farming and trade become formalised, rather than more being produced.",
     "GDP counts the output but not the distribution: average income can rise while most people see no gain.",
     "It ignores non-monetary factors - leisure, health, environmental quality, work-life balance."
    ]
   }
  ],
  "judge": "GDP per head is the most used measure and rises with income and employment, but it is an incomplete guide to living standards: it omits distribution, unpaid work and well-being, so it should be read alongside other measures.",
  "notes": [
   "Economic Growth"
  ]
 },
 "45": {
  "cols": [
   "Benefits of specialising in fishing",
   "Risks"
  ],
  "left": [
   {
    "title": "Specialisation raises output and efficiency",
    "steps": [
     "Concentrating on what you are relatively best at, then trading for everything else. Adam Smith’s pin factory is the founding example.",
     "Workers become faster and more skilled at a repeated task, raising output per worker.",
     "No time is lost switching between tasks.",
     "Training is cheaper and quicker when it covers one task rather than many.",
     "It makes mechanisation possible, since a single repeated task can be automated."
    ]
   }
  ],
  "right": [
   {
    "title": "Why specialisation may not help",
    "steps": [
     "Work becomes repetitive and boring, lowering motivation, raising absenteeism and staff turnover, and potentially reducing quality.",
     "Workers become occupationally immobile - a highly specialised skill is worthless if that industry declines, causing structural unemployment.",
     "Interdependence creates fragility: a breakdown in one stage halts the whole process, as global supply chain disruptions have shown.",
     "Less variety of output if firms all specialise in the same things."
    ]
   },
   {
    "title": "Dependence on one primary product",
    "steps": [
     "Relying on exporting one or two commodities makes income volatile and, some argue, doomed to decline.",
     "Commodity prices are volatile because both demand and supply are price inelastic in the short run: a small shift moves the price a lot.",
     "Prebisch-Singer: the terms of trade of primary exporters tend to deteriorate as world income grows.",
     "Dutch disease: a commodity boom raises the exchange rate and makes other exports uncompetitive, so the economy never diversifies."
    ]
   },
   {
    "title": "Prebisch-Singer: falling terms of trade",
    "steps": [
     "The commodity super-cycle of 2000-2014, driven by Chinese demand, improved the terms of trade of commodity exporters dramatically.",
     "Manufactures have become cheaper too: electronics prices fall relentlessly."
    ]
   }
  ],
  "judge": "Specialising in fishing can raise output through comparative advantage, but dependence on one primary product exposes an economy to price swings and the over-fishing of a resource that can run out.",
  "notes": [
   "Economic Methodology and the Economic Problem",
   "Factors Influencing Growth and Development",
   "Terms of Trade"
  ]
 },
