 "50": {
  "cols": [
   "How a recession raises unemployment",
   "Limits"
  ],
  "left": [
   {
    "title": "Cyclical unemployment",
    "steps": [
     "Unemployment caused by a lack of aggregate demand during a downturn.",
     "Labour is a DERIVED demand - firms hire workers to produce output, so when orders fall, hiring falls.",
     "Falling incomes reduce consumption, which reduces demand further: a negative multiplier effect.",
     "Firms cut hiring first, then hours, then jobs. Some fail entirely."
    ],
    "d": {
     "ids": [
      184
     ]
    }
   }
  ],
  "right": [
   {
    "title": "Why unemployment may not rise",
    "steps": [
     "It is temporary by nature and reverses when demand recovers, so it is less damaging than structural unemployment.",
     "Demand-side policy - fiscal or monetary stimulus - addresses this cause directly, so it is the most treatable type.",
     "Labour hoarding means firms may retain workers through a short downturn rather than pay to rehire and retrain later, so measured unemployment rises by less than output falls."
    ]
   },
   {
    "title": "Wage rigidity makes it worse",
    "steps": [
     "Wages held above the market-clearing level create an excess supply of labour.",
     "Trade union power, a national minimum wage set above equilibrium, or generous benefits raising the reservation wage.",
     "At the higher wage, quantity of labour supplied exceeds quantity demanded, and the gap is unemployment."
    ]
   }
  ],
  "judge": "A recession cuts AD and the demand for labour, so unemployment normally rises, by more where real wages are inflexible; the rise may be smaller where firms hold on to workers or people leave the labour force.",
  "notes": [
   "Employment and Unemployment"
  ]
 },
 "51": {
  "cols": [
   "Policies to reduce youth unemployment",
   "Limits of each policy"
  ],
  "left": [
   {
    "title": "Young people not in education, employment or training",
    "steps": [
     "A NEET is a young person (aged 16 to 24) who is not in education, employment or training.",
     "The UNEMPLOYED are actively seeking work and available to start. The ECONOMICALLY INACTIVE are neither working nor looking, often because of illness, caring responsibilities or discouragement.",
     "Poor health, mental health in particular, is a major factor: official analyses have found that a large share of NEETs have a health condition.",
     "Weak labour market conditions matter too, such as falling vacancies and payroll employment in sectors like hospitality that traditionally employ many young people."
    ]
   },
   {
    "title": "Education and training",
    "steps": [
     "Raises human capital, so workers are more productive and more occupationally mobile.",
     "Directly raises the quality of labour and hence output per worker.",
     "Reduces structural unemployment by closing the skills mismatch - especially where there are shortages, such as STEM.",
     "Attracts FDI, since firms locate where skilled labour is available."
    ]
   },
   {
    "title": "Tax and benefit reform",
    "steps": [
     "Reducing the wage replacement ratio raises the incentive to work and so raises the quantity of labour.",
     "The wage replacement ratio is the proportion of in-work income that benefits would replace. A ratio of 0.8 means benefits cover 80% of the wage - a weak incentive to take a job.",
     "Raising the personal allowance (currently £12,570) or cutting the basic rate raises the return to work.",
     "Lower or more tightly targeted benefits raise the incentive to enter the workforce.",
     "Cutting corporation tax raises retained profit: on £100m of profit, a 20% rate leaves £80m rather than £60m at 40% - money available for capital spending."
    ]
   }
  ],
  "right": [
   {
    "title": "Why NEET policies may not work",
    "steps": [
     "The two causes need different policies: health support and training address inactivity, while demand-side policy is needed when the problem is a shortage of jobs.",
     "This is a case where supply-side policy alone cannot work."
    ]
   },
   {
    "title": "Why training may not work",
    "steps": [
     "Enormous time lag - changes to primary education reach the workforce 14+ years later.",
     "It only works if the training matches what employers actually need; government has poor information about future skill demand.",
     "Significant opportunity cost, and the benefits are hard to attribute to any one policy.",
     "Trained workers may emigrate - a brain drain that transfers the return abroad."
    ]
   },
   {
    "title": "Structural unemployment takes time to fix",
    "steps": [
     "Unemployment caused by a change in the structure of the economy, leaving workers whose skills no longer match available jobs.",
     "Deindustrialisation: the long-run decline of an industry, such as UK coal and steel.",
     "Technological - capital replaces labour, e.g. self-service checkouts, automation.",
     "International - offshoring and outsourcing, or households buying imports instead of domestic output.",
     "Regional - unemployment concentrated in particular areas as an industry that dominated a region declines."
    ]
   }
  ],
  "judge": "Youth unemployment is largely structural (skills and experience), so education, training and help into work are the main policies, but they are slow and costly. Demand-side policy helps when the cause is cyclical.",
  "notes": [
   "Supply-Side Policy",
   "Employment and Unemployment"
  ]
 },
