     "Individuals consider only their own benefit and ignore the cost to third parties, so there is over-consumption Negative externality of PRODUCTION: flights from London to New YorkCOUNTED (private costs): fuel, aircraft, labour.",
     "IGNORED (external cost): global warming from greenhouse gas emissionsMSC is above MPC.",
     "Firms consider only their own costs, so there is over-production Positive externality of CONSUMPTION: educationCOUNTED (private benefits): higher future earnings, satisfaction from greater knowledge."
