 "70": {
  "cols": [
   "Factors the MPC considers",
   "Limits"
  ],
  "left": [
   {
    "title": "The inflation target",
    "steps": [
     "A specific inflation target has two benefits: it reduces inflation expectations, which avoids a wage-price spiral, and it improves consumer and business confidence, which supports growth.",
     "Type of targetWhat it meansExample SymmetricPolicy-makers must act if inflation falls BELOW target as well as if it rises above itThe Bank of England's 2% target, with a band of one percentage point either side AsymmetricAction is required only if inflation rises above the targetThe European Central Bank defined price stability as inflation \"below, but close to, 2%\" until it adopted a symmetric 2% target in 2021 A symmetric target is better for the UK because with an asymmetric one policy-makers are tempted to UNDERSHOOT the target, risking deflation and weak growth.",
     "The aim is more likely to be met if overshooting and undershooting count as equally bad."
    ]
   },
   {
    "title": "How rates transmit to AD",
    "steps": [
     "A RISE in Bank Rate reduces AD; a CUT raises it.",
     "Cost of borrowing - dearer credit reduces consumption of durables and reduces investment, since fewer projects clear the higher hurdle rate.",
     "Reward for saving - a higher return raises saving and reduces consumption.",
     "Mortgage payments - higher payments cut disposable income for mortgaged households. In the UK this is the largest channel.",
     "Asset prices and wealth - higher rates lower the present value of assets, so house and share prices fall, and the negative wealth effect cuts consumption."
    ]
   }
  ],
  "right": [
   {
    "title": "The output gap is hard to measure",
    "steps": [
     "Potential output cannot be observed. It is estimated from trend growth, capacity utilisation surveys and unemployment, and estimates are revised for years afterwards.",
     "GDP data itself is revised. The initial estimate of a quarter is often wrong by half a percentage point or more.",
     "The natural rate of unemployment, which defines \"full\" employment, is itself an estimate.",
     "A structural change - a productivity slowdown, a pandemic - shifts potential output in ways that only become clear in hindsight."
    ]
   },
   {
    "title": "Time lags and limits",
    "steps": [
     "Time lags of up to two years mean policy must be set on a forecast, and forecast error can make it pro-cyclical.",
     "Transmission is slow and uneven in the UK because most mortgages are on 2–5 year fixes, so a rate change reaches households only as fixes expire.",
     "The zero lower bound prevents meaningful further cuts in a deep recession.",
     "Confidence can dominate: in a downturn, firms will not invest and households will not borrow however cheap credit becomes.",
     "It is a blunt instrument - one rate applies to every region and sector, whatever their differing conditions."
    ]
   }
  ],
  "judge": "The MPC weighs inflation against its target first, then the output gap, wage growth and the state of the labour market; each is measured with error, so decisions rely on forecasts.",
  "notes": [
   "Monetary Policy",
   "Output Gaps and the Trade Cycle"
  ]
 },
