 "104": {
  "cols": [
   "Advantages of a free market in education",
   "Limits"
  ],
  "left": [
   {
    "title": "The invisible hand",
    "steps": [
     "Individuals pursuing self-interest are led, as if by an invisible hand, to an outcome that benefits society.",
     "Consumers maximise utility and firms maximise profit; the price mechanism coordinates them without any central direction.",
     "Prices signal scarcity, ration limited supply, and incentivise producers to move resources to where they are most valued."
    ]
   },
   {
    "title": "The market economy",
    "steps": [
     "Definition: Market economyAn economic system in which resources are allocated through the market forces of supply (firms) and demand (consumers), with no government involvement.",
     "A market economy is usually called capitalism: consumers and firms are motivated by maximising their own satisfaction and profit.",
     "Adam Smith put forward the \"invisible hand\" in The Wealth of Nations (1776): resources are allocated without the government having to direct them, which is an argument in favour of a market economy.",
     "This is why governments intervene: where the price mechanism fails to give the socially optimum allocation there is a welfare loss, and the government's aim is to maximise welfare."
    ]
   }
  ],
  "right": [
   {
    "title": "Why the invisible hand may fail",
    "steps": [
     "It only holds when there is no market failure.",
     "Externalities, public goods, information gaps and monopoly all break the result.",
     "It says nothing about EQUITY - an efficient outcome can be deeply unequal, since the market allocates to those with purchasing power, not to those with need.",
     "It assumes rationality and perfect information, both of which behavioural economics undermines."
    ]
   },
   {
    "title": "Education is a merit good",
    "steps": [
     "Goods whose private benefit is under-estimated by the consumer, so less is bought than is socially optimal.",
     "Education, healthcare, pensions, insurance. The benefits are long-term and uncertain, so people undervalue them at the point of decision.",
     "MPB lies below the true value (MSB), so consumption settles at Qm < Q*.",
     "Present bias reinforces it - costs are now, benefits are distant."
    ]
   },
   {
    "title": "Does the price mechanism allocate resources well?",
    "steps": [
     "In a competitive market with no market failure, yes - it achieves allocative efficiency where price equals marginal cost.",
     "It requires no central authority and no bureaucracy, and adjusts continuously to changing conditions.",
     "It uses dispersed local knowledge that no planner could collect (Hayek)."
    ]
   }
  ],
  "judge": "A free market gives choice and competition, which can raise quality, but education is a merit good with external benefits, so a free market under-provides it to the poor.",
  "notes": [
   "Economic Systems",
   "Public Goods and Information Gaps",
   "Price Determination and the Price Mechanism"
  ]
 },
