 "107": {
  "cols": [
   "How QE works in a recession",
   "Why it may not work"
  ],
  "left": [
   {
    "title": "Quantitative easing",
    "steps": [
     "Buying bonds raises their price and so lowers their yield, reducing long-term interest rates across the economy.",
     "It raises asset prices generally, producing a positive wealth effect.",
     "It increases banks’ liquidity, which should raise lending.",
     "Used when Bank Rate is already at the lower bound and conventional policy is exhausted."
    ]
   },
   {
    "title": "Quantitative easing, step by step",
    "steps": [
     "The central bank creates electronic money (in effect, printing money) and buys bonds, mostly government bonds, from financial institutions.",
     "The institutions now hold more cash, so they have more liquidity to lend.",
     "The central bank's demand raises bond prices and lowers their yields, so holding government bonds becomes unattractive.",
     "Investors move into corporate bonds (a little riskier but better yield) and shares. Higher demand lifts corporate bond prices and lowers their yields, so it becomes cheaper for firms to borrow by issuing bonds, which can encourage investment.",
     "Share prices rise, creating a wealth effect that raises consumption, and banks are encouraged to lend more."
    ]
   }
  ],
  "right": [
   {
    "title": "Why QE may not work",
    "steps": [
     "Banks may hold the extra reserves rather than lend, so the transmission to the real economy is weak - the money supply rises without AD rising.",
     "It inflates asset prices, and since asset ownership is concentrated, it worsens WEALTH INEQUALITY.",
     "This is the main political objection.",
     "It risks inflation if the money is not withdrawn as recovery arrives, and unwinding it (quantitative tightening) is untested at scale.",
     "It weakens the currency, raising import prices."
    ]
   },
   {
    "title": "The liquidity trap",
    "steps": [
     "CONFIDENCE was very low. High interest rates were not what was putting people off spending, so further cuts could not solve the problem.",
     "Banks did not pass cuts on, because they wanted to hold on to deposits to improve their own liquidity and were not keen to lend.",
     "Banks were unwilling to lend to EACH OTHER, again to protect their liquidity, and inter-bank lending is essential for financial markets to function."
    ]
   }
  ],
  "judge": "QE lowers long-term rates and raises asset prices and liquidity, which supports demand, but banks may hold the money, it raises wealth inequality and the evidence on its size is mixed.",
  "notes": [
   "Monetary Policy"
  ]
 },
