     "TechnicalLarge-scale capital - a production line, a bigger ship - spreads its cost over more units.",
     "Includes the container principle: doubling a tanker’s surface area more than doubles its volume.",
     "FinancialBanks lend to large firms at lower interest rates because they are lower risk and have more collateral.",
     "ManagerialSpecialist managers can be employed - a dedicated finance director, HR director - raising productivity through the division of labour."
