 "133": {
  "cols": [
   "Why a deficit is significant",
   "Why it may not be"
  ],
  "left": [
   {
    "title": "Consequences of a persistent deficit",
    "steps": [
     "ConsequenceExplanation Withdrawal from the circular flowA rising deficit means (X − M) falls, so AD falls: output falls, derived demand for labour falls, unemployment and benefit spending rise, tax revenue falls, and the budget deficit widens.",
     "Structural unemploymentFalling exports and rising imports cause deindustrialisation, concentrated regionally.",
     "Debt burden and loss of confidenceThe deficit is financed by a financial account surplus - foreign purchases of UK assets and government bonds.",
     "If investors doubt the ability to repay, interest rates rise and capital may leave suddenly.",
     "Loss of policy freedomCountries in a currency union cannot devalue, so adjustment must come through wages and prices - the southern European experience between 2000 and 2007."
    ]
   },
   {
    "title": "Poor international competitiveness",
    "steps": [
     "If domestic goods are dearer or lower quality than foreign ones, exports fall and imports rise.",
     "Higher domestic inflation than trading partners erodes price competitiveness.",
     "Low productivity growth raises unit labour costs.",
     "A strong exchange rate makes exports dear and imports cheap.",
     "Weak non-price competitiveness - design, reliability, branding, after-sales service."
    ]
   },
   {
    "title": "Financing a deficit and its risks",
    "steps": [
     "A current account deficit must be financed by a corresponding surplus on the financial account - i.e. net inflows of foreign investment/lending.",
     "This is sustainable if financed by stable, long-term flows (e.g. foreign direct investment), but riskier if reliant on volatile short-term \"hot money\" flows that could reverse quickly if investor sentiment changes, potentially forcing a disorderly currency depreciation or requiring a sharp rise in domestic interest rates to retain investor confidence."
    ]
   }
  ],
  "right": [
   {
    "title": "Is a deficit necessarily a problem?",
    "steps": [
     "It depends onWhy Its size relative to GDPA few percent of GDP is easily financed; a large deficit is not.",
     "How long it persistsA cyclical deficit corrects itself; a structural one does not.",
     "How it is financedLong-term FDI is stable and productive; short-term \"hot money\" can reverse overnight.",
     "What the imports areCapital goods raise future capacity; consumer goods do not.",
     "The exchange rate regimeA floating rate adjusts automatically to correct a deficit; a fixed rate does not."
    ]
   },
   {
    "title": "Can a deficit be a good thing?",
    "steps": [
     "Positive consequenceExplanation It brings capacity-raising investmentA current account deficit means a financial account SURPLUS, for example high inward direct investment.",
     "Foreign firms bring capital, jobs, technology and new working practices: Japanese car makers raised labour productivity in the UK.",
     "Investment in infrastructure, such as Chinese-financed projects in Africa like a coastal railway in Nigeria, can raise incomes and tax revenue, which can be spent on health and education to improve development Automatic correctionA large deficit tends to cause the currency to depreciate under a floating rate, which makes exports cheaper and imports dearer and so reduces the deficit It may reflect high incomesRich consumers buy a greater variety of better goods at lower prices from around the world, and firms gain from cheaper inputs, which is not a cause for concern It may reflect demographicsPeople aged about 40 to 65 save for retirement and tend to run surpluses, while retirees run down savings and spend heavily on imports Whether a deficit is a concern depends onWhy Its size relative to GDPA deficit of over about 5% of GDP is more worrying because it relies heavily on foreigners continuing to invest.",
     "If that stops there can be a sharp depreciation and cost-push inflation Developed or developingA country like the USA can attract capital flows by selling dollar securities, so has less to fear.",
     "A developing economy is more vulnerable because investors are quicker to fear a downturn and withdraw their money The causeA large, persistent deficit may signal weak competitiveness and weak supply-side policy; or it may simply reflect high incomes or demographics How it is financedBorrowing to fund investment that raises productive capacity is healthy; borrowing to fund consumption is not"
    ]
   }
  ],
  "judge": "A persistent deficit must be financed by borrowing or selling assets, which raises debt and exposes the economy to a loss of confidence, but a deficit from investment in a growing economy is much less worrying.",
  "notes": [
   "Balance of Payments",
   "The Balance of Payments"
  ]
 },
