  "left": [
   {
    "title": "Growth against inflation",
    "steps": [
     "Demand-led growth near full capacity causes demand-pull inflation.",
     "AD rises → the economy moves up the AS curve → the price level rises.",
     "The nearer to capacity, the more of the shift goes into prices rather than output."
    ]
   },
   {
    "title": "Growth against the current account",
    "steps": [
     "Rising incomes raise import demand, particularly given the UK’s high marginal propensity to import.",
     "Firms may divert output from export markets to the buoyant domestic market."
    ]
   },
   {
    "title": "The budget against everything else",
    "steps": [
     "Reducing a budget deficit conflicts with growth and employment in the short run.",
     "Spending cuts or tax rises reduce AD directly, and the negative multiplier amplifies the fall.",
     "This is the austerity debate: consolidating in a downturn deepens the downturn and may not even reduce the debt ratio, since GDP falls too."
    ]
   },
   {
    "title": "The Phillips curve",
    "steps": [
     "A demand boost lowers unemployment below the natural rate and raises inflation.",
     "Workers come to EXPECT the higher inflation and build it into wage demands, so real wages return to their previous level.",
     "Employment falls back to the natural rate, but now with higher inflation - the short-run curve has shifted outwards.",
     "Only a further, larger dose of inflation can hold unemployment below the natural rate; sustaining it means accelerating inflation."
    ]
   }
  ],
  "right": [
   {
    "title": "Why the short-run curve has flattened",
    "steps": [
     "Workers have less bargaining power than they once did, so falling unemployment pushes wages up by less.",
     "Union membership fell from about 38% of employees in 1990 to about 23% by 2016, and is lower still in the private sector, while self-employment, part-time and temporary work (the gig economy) have grown.",
     "Globalisation and digitalisation: workers hesitate to ask for pay rises for fear that their jobs will be outsourced or offshored.",
     "Migration from the EU after 2004 may have helped to dampen wage growth."
    ]
   },
   {
    "title": "The long-run Phillips curve is vertical",
    "steps": [
     "In the long run there is no trade-off: unemployment returns to its natural rate whatever the inflation rate.",
     "A demand boost lowers unemployment below the natural rate and raises inflation.",
     "Workers come to EXPECT the higher inflation and build it into wage demands, so real wages return to their previous level.",
     "Employment falls back to the natural rate, but now with higher inflation - the short-run curve has shifted outwards.",
     "Only a further, larger dose of inflation can hold unemployment below the natural rate; sustaining it means accelerating inflation."
    ]
   }
  ],
  "judge": "Expansionary policy raises growth and cuts unemployment but risks inflation, a wider deficit and a current account deficit; the conflict is greatest near full capacity and small when there is spare capacity.",
