     "But the supernormal profit may fund innovation designed to keep barriers high and prevent future entry X-efficiencyNoWithout competitive pressure, organisational slack can develop Consumer welfare featurePresent?Why Low pricesNoMarket power and barriers let the firm restrict output and charge high prices without fear of entry High qualityUnlikelyConsumers have nowhere else to go, so there is little incentive to improve.",
     "Supernormal profit may still be spent on innovation to protect the barriers ChoiceNoThere is only one firm"
