 "183": {
  "cols": [
   "Two reasons most firms are small, apart from finance",
   ""
  ],
  "left": [
   {
    "title": "Why small firms stay small",
    "steps": [
     "The two routes suit firms at opposite ends of the size distribution, for three connected reasons.",
     "External growth is EXPENSIVE - only large firms can raise the finance to buy another company outright.",
     "Small firms have a great deal of scope left for organic growth: many potential customers have simply never encountered their product yet, so ordinary expansion still has room to run.",
     "Large firms often face STAGNATING sales in their existing market, so they look to other firms - often in other markets - where sales are still growing."
    ]
   },
   {
    "title": "The minimum efficient scale is small",
    "steps": [
     "It determines the structure of the industry.",
     "Where MES is LARGE relative to market demand, only a few firms can operate efficiently - this produces oligopoly or natural monopoly.",
     "Where MES is SMALL, many firms can achieve minimum cost, so the market supports competition.",
     "A firm below MES has higher unit costs than rivals and cannot compete on price, which is itself a barrier to entry."
    ]
   }
  ],
  "right": [],
  "notes": [
   "Business Growth",
   "Economies and Diseconomies of Scale"
  ]
 },
