 "196": {
  "cols": [
   "Costs of a monopsony",
   "Limits"
  ],
  "left": [
   {
    "title": "How a monopsonist sets price and quantity",
    "steps": [
     "Because it is the only buyer, buying one more unit raises the price it pays for EVERY unit, so the marginal cost of a unit exceeds its price.",
     "The supply curve it faces is the whole market supply - upward sloping.",
     "To buy more it must offer a higher price, and that higher price applies to all units, so the marginal cost curve lies ABOVE the supply curve.",
     "It buys where MC of buying = marginal revenue product (or marginal benefit), which is FEWER units than a competitive market would buy.",
     "It then pays only the price on the supply curve for that quantity, which is BELOW what a competitive market would pay."
    ]
   },
   {
    "title": "Who gains and who loses",
    "steps": [
     "StakeholderEffect of monopsony power The monopsonist firmLower input costs, higher profit; may pass some on as lower prices to consumers, or keep it Suppliers / workersLower prices or wages than their contribution justifies; squeezed margins; farmers driven out; workers underpaid ConsumersPossibly lower prices if cost savings are passed on - but not if the firm also has monopoly power in its selling market Employees of the monopsonistAmbiguous: a profitable employer may be more secure, but the same power may be used against its own workforce EfficiencyAllocatively inefficient: too little is bought at too low a price; the deadweight loss mirrors monopoly"
    ]
   }
  ],
  "right": [
   {
    "title": "Monopsony in practice",
    "steps": [
     "UK supermarkets and their suppliers: the Groceries Code Adjudicator exists because of evidence of delayed payments, retrospective price changes and forced promotions.",
     "The NHS as the near-sole employer of nurses and buyer of drugs: it can hold down wages and prices, but persistent shortages suggest the wage is below the market-clearing level.",
     "Large online platforms as buyers of labour and of sellers' output."
    ]
   },
   {
    "title": "Protecting suppliers and employees",
    "steps": [
     "Statutory codes of practice - the Groceries Supply Code of Practice, policed by the Groceries Code Adjudicator - restrict how supermarkets can treat food suppliers, banning practices such as retrospective price cuts.",
     "A minimum wage counters monopsony power over LOW-paid workers directly, as covered in Wage Determination: it can raise both pay and employment where a single dominant employer was holding wages below the competitive level.",
     "Sector regulators can require minimum notice periods, fair contract terms, or independent arbitration for disputes between a dominant buyer and its suppliers."
    ]
   },
   {
    "title": "The minimum wage under monopsony",
    "steps": [
     "This is the case where a minimum wage can raise employment as well as pay, which is why the empirical evidence on minimum wages is mixed rather than uniformly negative.",
     "A minimum wage set between the monopsony wage and the competitive wage makes the marginal cost of labour constant at that wage, removing the wedge.",
     "The firm then hires where the minimum wage equals MRP, which is a HIGHER quantity than before.",
     "So pay rises and employment rises simultaneously - the opposite of the competitive prediction."
    ]
   }
  ],
  "judge": "A monopsony pays suppliers less and buys less than a competitive market, so suppliers lose and output falls; consumers can gain from lower prices, so the cost depends on whether savings are passed on.",
  "notes": [
   "Monopsony",
   "Government Intervention and Equity",
   "Wage Determination"
  ]
 },
