 "200": {
  "cols": [
   "Policies to reduce labour immobility",
   "Limits"
  ],
  "left": [
   {
    "title": "Immobility of labour and capital",
    "steps": [
     "Resources that cannot move between uses or places are misallocated, so the economy operates inside its PPF.",
     "Occupational immobility: a redundant steelworker cannot become a software developer without retraining, so the skills mismatch causes structural unemployment.",
     "Geographical immobility: housing costs, family ties and transport prevent moving to where the jobs are - which is why UK unemployment is regionally concentrated.",
     "Capital can be immobile too: a specialised factory has no alternative use, so its resources are stranded when the industry declines."
    ]
   },
   {
    "title": "Education and training",
    "steps": [
     "Raises human capital, so workers are more productive and more occupationally mobile.",
     "Directly raises the quality of labour and hence output per worker.",
     "Reduces structural unemployment by closing the skills mismatch - especially where there are shortages, such as STEM.",
     "Attracts FDI, since firms locate where skilled labour is available."
    ]
   },
   {
    "title": "Labour mobility",
    "steps": [
     "Immobility keeps supply low in a particular market even when wages are high.",
     "Occupational immobility: skills do not transfer between jobs.",
     "Geographical immobility: housing costs, family ties and transport prevent moving to where work is."
    ]
   }
  ],
  "right": [
   {
    "title": "Why immobility is hard to fix",
    "steps": [
     "Some immobility is temporary and resolves as people retrain and relocate over years.",
     "Policy can reduce it - retraining, relocation support, affordable housing - but only slowly and at significant cost.",
     "Perfect mobility would be undesirable if it meant no one had specialised skills at all."
    ]
   },
   {
    "title": "Why training may not work",
    "steps": [
     "Enormous time lag - changes to primary education reach the workforce 14+ years later.",
     "It only works if the training matches what employers actually need; government has poor information about future skill demand.",
     "Significant opportunity cost, and the benefits are hard to attribute to any one policy.",
     "Trained workers may emigrate - a brain drain that transfers the return abroad."
    ]
   }
  ],
  "judge": "Retraining and help with moving reduce occupational and geographical immobility, but they are slow and costly, and housing costs and family ties keep many workers where they are.",
  "notes": [
   "Types of Market Failure",
   "Supply-Side Policy",
   "Wage Determination"
  ]
 },
 "201": {
  "cols": [
   "How nationalisation could protect employees",
   "Limits"
  ],
  "left": [
   {
    "title": "Nationalisation and privatisation",
    "steps": [
     "Nationalisation - arguments FORPrivatisation - arguments FOR Natural monopoly avoids wasteful duplication of networksProfit motive drives efficiency and cost reduction Externalities and social objectives can be pursued directlyRemoves political interference from investment decisions Avoids private monopoly exploiting consumersRaises revenue for government and widens share ownership Can guarantee universal service in unprofitable areasCompetition where it is possible improves choice and quality"
    ]
   },
   {
    "title": "Employees",
    "steps": [
     "A monopoly’s effect on its own workforce cuts in genuinely opposite directions, which is why this is a reliable evaluation point.",
     "Secure supernormal profit can fund higher wages, better training and greater job security than a firm surviving on normal profit in a competitive market could offer.",
     "But a monopoly facing no competitive pressure has less need to keep employees productive or satisfied, and X-inefficiency can show up as bloated management layers rather than as higher pay for frontline workers.",
     "A monopoly is often also a monopsony in its local labour market - the dominant or only employer of a particular skill in a region - in which case it can hold wages BELOW the competitive level even while charging consumers above it."
    ]
   }
  ],
  "right": [
   {
    "title": "The cost of subsidy and nationalisation",
    "steps": [
     "Both solve the pricing problem but create a different inefficiency.",
     "With a subsidy the firm can only ever earn normal profit, so it has no incentive to control costs: if costs rise, the government simply pays more. The firm may also misreport its costs.",
     "NATIONALISATION (the state runs the industry) lets economies of scale be enjoyed without the firm exploiting consumers, because it is no longer a profit maximiser. Governments have taken train operators into public ownership for this kind of reason.",
     "The drawback is again X-inefficiency, because there is no profit incentive."
    ]
   },
   {
    "title": "Why employees may not gain",
    "steps": [
     "Which effect dominates depends on whether the monopoly profit is shared with the workforce or captured by shareholders and management - a question about bargaining power and union presence as much as about market structure."
    ]
   }
  ],
  "judge": "Public ownership can protect pay and jobs because profit is not the only aim, but it may be less efficient and need subsidy, which can threaten the jobs it aims to protect.",
  "notes": [
   "Government Intervention and Equity",
   "Monopoly"
  ]
 },
